from fpdf import FPDF

class _BorderedPDF(FPDF):
    """FPDF subclass that draws a light corner/frame border on every page automatically
       (via header(), which fpdf2 calls right after every add_page())."""
    def header(self):
        self.set_draw_color(180, 180, 180)
        self.set_line_width(0.4)
        self.rect(6, 6, self.w - 12, self.h - 12)


