def _pdf_logo_band(pdf, band_h=26, bg_rgb=(10, 46, 36)):
    """A dark footer band with the Sunsure Energy logo centered on it. The source logo PNG is
       white-on-transparent (verified: pixel RGB ~(255,255,254) at full opacity, alpha varying) --
       it is invisible on a plain white page, so it always needs a dark background band like this
       one behind it, not a bare pdf.image() call."""
    was_auto = pdf.auto_page_break
    pdf.set_auto_page_break(auto=False)
    # If whatever's already on the page runs into where this band would sit, put the band on a
    # fresh page instead of drawing over existing content.
    if pdf.get_y() > pdf.h - band_h - 5:
        pdf.add_page(same=True)
    y0 = pdf.h - band_h
    pdf.set_fill_color(*bg_rgb)
    pdf.rect(0, y0, pdf.w, band_h, style="F")
    logo_bytes = base64.b64decode(SUNSURE_LOGO_B64)
    # Source logo is 540x126px (aspect ~4.29:1); size it to fit within the band with margin.
    logo_w = min(70, pdf.w * 0.35)
    logo_h = logo_w / (540/126)
    pdf.image(io.BytesIO(logo_bytes), x=(pdf.w-logo_w)/2, y=y0+(band_h-logo_h)/2, w=logo_w)
    pdf.set_auto_page_break(auto=was_auto, margin=15)


