def _pdf_letterhead_footer(pdf, img_w=130, bottom_margin=14):
    """Sunsure Energy company letterhead (logo + legal name + registered address + contact
       details) on a plain white background -- closes the first and last pages of a report.
       Unlike the plain white-on-transparent logo mark (_pdf_logo_band), this asset already
       includes its own text and is designed to sit directly on white, so no colored background
       band is drawn behind it. `bottom_margin` keeps it clear of the page border drawn by
       _BorderedPDF (at 6mm from the edge) instead of touching/overlapping it."""
    was_auto = pdf.auto_page_break
    pdf.set_auto_page_break(auto=False)
    img_h = img_w / (1267/430)
    band_h = img_h + bottom_margin
    # If whatever's already on the page runs into where this footer would sit, put it on a
    # fresh page instead of drawing over existing content.
    if pdf.get_y() > pdf.h - band_h - 5:
        pdf.add_page(same=True)
    y0 = pdf.h - band_h
    logo_bytes = base64.b64decode(SUNSURE_LETTERHEAD_B64)
    pdf.image(io.BytesIO(logo_bytes), x=(pdf.w-img_w)/2, y=y0, w=img_w)
    pdf.set_auto_page_break(auto=was_auto, margin=15)

