UP_VOLTAGE_TABLE = {
    # basic = Basic Energy Charge (Rs/kWh); dist_loss = distribution loss; wheeling = wheeling charge (Rs/kWh).
    # NOTE (from the source workbook): wheeling charges for Below 11 kV / At 11 kV / At 33 kV are PLACEHOLDERS
    # (0.9318 x 50%) pending the actual UPPCL wheeling order; wheeling is exempt above 33 kV (UP Solar Energy
    # Policy / CRE Regs 2024).
    "Below 11 kV":                         dict(basic=7.1, dist_loss=0.1307, exempt=False, wheeling=0.9318*0.5),
    "At 11 kV":                            dict(basic=7.1, dist_loss=0.08,   exempt=False, wheeling=0.9318*0.5),
    "At 33 kV":                            dict(basic=6.8, dist_loss=0.03,   exempt=False, wheeling=0.9318*0.5),
    "Above 33kV up to 132kV (66kV/132kV)": dict(basic=6.4, dist_loss=0.01,   exempt=True,  wheeling=0.0),
    "Above 132 kV":                        dict(basic=6.1, dist_loss=0.01,   exempt=True,  wheeling=0.0),
}
UP_SLOT_KEYS = ["TOD1", "TOD2", "TOD3", "TOD4"]
UP_SLOT_HRS = {"summer": {"TOD1": 5, "TOD2": 9, "TOD3": 8, "TOD4": 2},
               "winter": {"TOD1": 6, "TOD2": 6, "TOD3": 6, "TOD4": 6}}
# (summer hours, winter hours) as shown to the customer; Summer = Apr-Sep, Winter = Oct-Mar.
UP_TOD_HOURS_TXT = {"TOD1": ("5am-10am", "5am-11am"), "TOD2": ("10am-7pm", "11am-5pm"),
                    "TOD3": ("7pm-3am", "5pm-11pm"),  "TOD4": ("3am-5am", "11pm-5am")}
UP_TOD_NOTE = {"TOD1": "Rebate in summer", "TOD2": "Straight", "TOD3": "Peak (surcharge)", "TOD4": "Rebate in winter"}
# Hamirpur's total project size (MWp / MW AC), shown on the report cover. Set either to None to fall back to
# the capacity selected in the dashboard instead.
UP_PLANT_SOLAR_MWP  = 75.0
UP_PLANT_SOLAR_MWAC = 50.0

def up_tod(h, m):
    """ToD slot for hour-of-day h in month index m (0 = April). Summer = Apr-Sep, Winter = Oct-Mar."""
    if m < 6:
        if 5 <= h <= 9:   return "TOD1"
        if 10 <= h <= 18: return "TOD2"
        if h >= 19 or h <= 2: return "TOD3"
        return "TOD4"
    if 5 <= h <= 10:  return "TOD1"
    if 11 <= h <= 16: return "TOD2"
    if 17 <= h <= 22: return "TOD3"
    return "TOD4"

def up_cons_hr_from_tod(tod_kwh):
    """tod_kwh: {'TOD1': [12 monthly kWh], ...} -> {hour: [12 monthly kWh totals]}, spreading each slot's monthly
       total evenly over its hours (summer 5/9/8/2 hrs, winter 6/6/6/6 hrs, matching the workbook)."""
    out = {h: [0.0]*12 for h in range(24)}
    for m in range(12):
        hrs = UP_SLOT_HRS["summer" if m < 6 else "winter"]
        for h in range(24):
            s = up_tod(h, m)
            out[h][m] = tod_kwh[s][m]/hrs[s]
    return out

def up_cons_hr_flat(load_mw):
    return {h: [load_mw*1000*DAYS[m] for m in range(12)] for h in range(24)}

def run_up(solar_dc, ex_bus_tariff, voltage, load_mw=None, cons_hr_override=None,
           transmission_loss=0.0318, wheeling_loss=0.01, ed_pct=0.075, fuel_pct=0.0177, tod_pct=0.15,
           banking_loss=0.08, inj_ceiling=0.25, cons_ceiling=0.30, state_trans_rate=0.15375,
           sldc_fees=15000.0, sldc_sched=158896.0, ltoa=50000.0, css=0.0, add_surcharge=0.0,
           wheeling_charge=None, basic_charge=None, dist_loss=None):
    """Uttar Pradesh (Hamirpur, Solar-only) engine -- replicates UP_OA_Solar_Hamirpur_Claude.xlsx: monthly-typical
       hourly profiles (24h x 12 months), real-time settlement, FIFO banking ledger (UPERC CRE Regulations 2024,
       banking charge deducted AT WITHDRAWAL), ToD x season grid tariff, solar landed-tariff build-up and savings.
       Validated against the workbook's cached outputs. All energy in kWh unless named *_mwh."""
    V = UP_VOLTAGE_TABLE[voltage]
    base = V["basic"] if basic_charge is None else basic_charge          # Rs/kWh -- tier default unless overridden
    dist_loss_used = V["dist_loss"] if dist_loss is None else dist_loss  # tier default unless overridden; reduces delivered energy
    wheel_rate = V["wheeling"] if wheeling_charge is None else wheeling_charge
    cons_hr = cons_hr_override if cons_hr_override is not None else up_cons_hr_flat(load_mw if load_mw is not None else 0.0)

    # Delivered at the customer busbar = generation x (1-transmission loss) x (1-wheeling loss) x (1-distribution loss).
    # NOTE: the source workbook does not apply distribution loss here (it is used there only for CSS); it is applied
    # here so the voltage tier / distribution-loss input flows through to settlement, RE displacement and savings.
    # Setting distribution loss to 0 reproduces the workbook exactly.
    deliver = (1-transmission_loss)*(1-wheeling_loss)*(1-dist_loss_used)
    gen_pre = {h: [UP_HAMIRPUR_PROFILE[h][m]*solar_dc for m in range(12)] for h in range(24)}
    gen_del = {h: [gen_pre[h][m]*deliver for m in range(12)] for h in range(24)}
    inj_mo = [sum(gen_pre[h][m] for h in range(24)) for m in range(12)]
    del_mo = [sum(gen_del[h][m] for h in range(24)) for m in range(12)]
    cons_mo = [sum(cons_hr[h][m] for h in range(24)) for m in range(12)]

    rtc_mo, res_np_mo, res_pk_mo = [], [], []
    resid_by_slot, cons_by_slot, inj_by_slot = [], [], []
    for m in range(12):
        rtc = npk = pk = 0.0
        rs = {s: 0.0 for s in UP_SLOT_KEYS}; fc = {s: 0.0 for s in UP_SLOT_KEYS}; ij = {s: 0.0 for s in UP_SLOT_KEYS}
        for h in range(24):
            g, c = gen_del[h][m], cons_hr[h][m]
            rtc += min(g, c)
            res = max(c-g, 0.0)
            s = up_tod(h, m)
            rs[s] += res; fc[s] += c; ij[s] += gen_pre[h][m]
            if s == "TOD3": pk += res        # TOD3 = peak: never covered by banking
            else:           npk += res
        rtc_mo.append(rtc); res_np_mo.append(npk); res_pk_mo.append(pk)
        resid_by_slot.append(rs); cons_by_slot.append(fc); inj_by_slot.append(ij)

    # ---- FIFO banking ledger (Banking sheet, Section D) ----
    bbf = 0.0
    L = {k: [] for k in ("bbf", "be", "we", "bc", "adj", "bcf", "cap", "carry", "lapse1", "banked", "np_resid")}
    for m in range(12):
        be = (del_mo[m]-rtc_mo[m]) + bbf
        we = res_np_mo[m]
        bc = min(we, be)*banking_loss
        if be > we and banking_loss*min(be, we) < (be-we):
            adj = min(be, we)
        else:
            adj = be - bc
        bcf = max(be-adj-bc, 0.0)
        cap = max(del_mo[m]*inj_ceiling, cons_ceiling*(cons_mo[m]-rtc_mo[m]))
        carry = min(max(bcf, 0.0), cap)
        lapse1 = max(bcf-cap, 0.0)
        banked = min(we, adj)
        for k, v in zip(L.keys(), (bbf, be, we, bc, adj, bcf, cap, carry, lapse1, banked, we-banked)):
            L[k].append(v)
        bbf = carry
    lapsed_mo = list(L["lapse1"]); lapsed_mo[11] += L["carry"][11]    # closing carry-forward treated as lapse (Banking!P155)

    tot_inj, tot_del, tot_cons = sum(inj_mo), sum(del_mo), sum(cons_mo)
    tot_rtc, tot_banked, tot_bc = sum(rtc_mo), sum(L["banked"]), sum(L["bc"])
    lapse_total = sum(lapsed_mo)
    np_resid, pk_resid = sum(L["np_resid"]), sum(res_pk_mo)
    resid = np_resid + pk_resid
    settled = tot_rtc + tot_banked
    td_loss = tot_inj - tot_del

    # ---- Grid tariff by ToD x season (Tariff sheet, Section 4) ----
    straight = base + base*ed_pct + base*fuel_pct
    rebate = (base + base*ed_pct)*(1-tod_pct) + base*fuel_pct
    surch = (base + base*ed_pct)*(1+tod_pct) + base*fuel_pct
    summer_t = {"TOD1": rebate, "TOD2": straight, "TOD3": surch, "TOD4": straight}
    winter_t = {"TOD1": straight, "TOD2": straight, "TOD3": surch, "TOD4": rebate}
    sf = {s: sum(cons_by_slot[m][s] for m in range(6)) for s in UP_SLOT_KEYS}
    wf = {s: sum(cons_by_slot[m][s] for m in range(6, 12)) for s in UP_SLOT_KEYS}
    cost_before = sum(sf[s]*summer_t[s] + wf[s]*winter_t[s] for s in UP_SLOT_KEYS)

    # ---- Residual-grid cost rate (Savings sheet, cost build-up block) ----
    s_np = {s: sum(resid_by_slot[m][s] for m in range(6)) for s in ("TOD1", "TOD2", "TOD4")}
    w_np = {s: sum(resid_by_slot[m][s] for m in range(6, 12)) for s in ("TOD1", "TOD2", "TOD4")}
    H19 = sum(s_np[s]*summer_t[s] for s in s_np)/sum(s_np.values()) if sum(s_np.values()) else 0.0
    I19 = sum(w_np[s]*winter_t[s] for s in w_np)/sum(w_np.values()) if sum(w_np.values()) else 0.0
    F19, G19 = sum(L["np_resid"][:6]), sum(L["np_resid"][6:])
    F20, G20 = sum(res_pk_mo[:6]), sum(res_pk_mo[6:])
    resid_rate = ((F19*H19 + G19*I19 + F20*summer_t["TOD3"] + G20*winter_t["TOD3"])/(F19+G19+F20+G20)) if resid > 0 else 0.0

    # ---- Solar landed-tariff build-up (Tariff sheet, Section 6) ----
    inj_stu = tot_inj*(1-transmission_loss)
    at_wheel = inj_stu*(1-wheeling_loss)
    at_buyer = at_wheel*(1-dist_loss_used)
    delivered_w = at_buyer - tot_bc
    solar_cost = tot_inj*ex_bus_tariff
    trans_chg = tot_inj*state_trans_rate
    wheel_chg = inj_stu*wheel_rate
    fixed_chg = sldc_fees + sldc_sched + ltoa
    lapse_impact = lapse_total*(solar_cost/delivered_w) if delivered_w > 0 else 0.0
    total_cost = solar_cost + trans_chg + wheel_chg + fixed_chg + css + add_surcharge + lapse_impact
    landed = total_cost/delivered_w if delivered_w > 0 else 0.0
    if delivered_w > 0 and inj_stu > 0 and at_wheel > 0 and at_buyer > 0:
        comps = [
            ("RE Tariff (ex-bus)", ex_bus_tariff),
            ("Transmission Loss Impact", solar_cost/inj_stu - ex_bus_tariff),
            ("Wheeling Loss Impact", solar_cost/at_wheel - solar_cost/inj_stu),
            ("Distribution Loss Impact", solar_cost/at_buyer - solar_cost/at_wheel),
            ("Banking Loss Impact", solar_cost/delivered_w - solar_cost/at_buyer),
            ("State Transmission Charge", trans_chg/delivered_w),
            ("Wheeling Charge", wheel_chg/delivered_w),
            ("SLDC & LTOA Charges", fixed_chg/delivered_w),
            ("CSS & Additional Surcharge", (css+add_surcharge)/delivered_w),
            ("Lapsation Impact", lapse_impact/delivered_w),
        ]
    else:
        comps = [("RE Tariff (ex-bus)", ex_bus_tariff)]

    # ---- Savings (Savings sheet) ----
    cost_re_cr = settled*landed/1e7
    cost_resid_cr = resid*resid_rate/1e7
    total_cr = cost_re_cr + cost_resid_cr
    before_cr = cost_before/1e7
    sav_cr = before_cr - total_cr

    tod = {}
    for s in UP_SLOT_KEYS:
        c_s, c_w = sf[s], wf[s]
        c_all = c_s + c_w
        tod[s] = dict(cons_summer=c_s, cons_winter=c_w, cons=c_all,
                      tariff_summer=summer_t[s], tariff_winter=winter_t[s],
                      avg_tariff=(c_s*summer_t[s] + c_w*winter_t[s])/c_all if c_all else 0.0,
                      cost_cr=(c_s*summer_t[s] + c_w*winter_t[s])/1e7,
                      injected=sum(inj_by_slot[m][s] for m in range(12)))
    mwh = lambda arr: [v/1000 for v in arr]
    mo = dict(
        inj=mwh(inj_mo), gen=mwh(del_mo), cons=mwh(cons_mo), rts=mwh(rtc_mo), banked=mwh(L["banked"]),
        settled=mwh([rtc_mo[m] + L["banked"][m] for m in range(12)]),
        residual=mwh([cons_mo[m] - rtc_mo[m] - L["banked"][m] for m in range(12)]),
        lapsed=mwh(lapsed_mo), bank_loss=mwh(L["bc"]),
        **{f"cons_{s.lower()}": mwh([cons_by_slot[m][s] for m in range(12)]) for s in UP_SLOT_KEYS},
        **{f"inj_{s.lower()}": mwh([inj_by_slot[m][s] for m in range(12)]) for s in UP_SLOT_KEYS},
    )
    tol = max(1.0, tot_cons*1e-9)
    checks = dict(
        check1=abs((tot_rtc + tot_banked + np_resid + pk_resid) - tot_cons) < tol,         # RTC+Banked+Residual = Consumption
        check2=abs(tot_del - (tot_rtc + tot_banked + tot_bc + lapse_total)) < tol,         # Delivered = RTC+Banked+Loss+Lapse
        check3=abs(tot_inj - (tot_rtc + tot_banked + tot_bc + lapse_total + td_loss)) < tol,  # Injection fully accounted for
    )
    return dict(
        solar_dc=solar_dc, solar_ac=solar_dc/1.5, voltage=voltage, tier=V, ex_bus=ex_bus_tariff, wheel_rate=wheel_rate,
        basic=base, dist_loss=dist_loss_used,
        tot_inj=tot_inj, tot_del=tot_del, tot_cons=tot_cons, tot_rtc=tot_rtc, tot_banked=tot_banked, tot_bc=tot_bc,
        lapse_total=lapse_total, np_resid=np_resid, pk_resid=pk_resid, resid=resid, settled=settled, td_loss=td_loss,
        re_disp=settled/tot_cons if tot_cons else 0.0, rts_pct=tot_rtc/tot_inj if tot_inj else 0.0,
        bank_pct=tot_banked/tot_inj if tot_inj else 0.0, lapse_pct=lapse_total/tot_inj if tot_inj else 0.0,
        bc_pct=tot_bc/tot_inj if tot_inj else 0.0, td_pct=td_loss/tot_inj if tot_inj else 0.0,
        grid_before=cost_before/tot_cons if tot_cons else 0.0, landed=landed, resid_rate=resid_rate,
        post_oa_blended=total_cr*1e7/tot_cons if tot_cons else 0.0,
        before_cr=before_cr, cost_re_cr=cost_re_cr, cost_resid_cr=cost_resid_cr, total_cr=total_cr, sav_cr=sav_cr,
        sav_pct=sav_cr/before_cr if before_cr else 0.0,
        sav_per_unit=(before_cr - total_cr)*1e7/tot_cons if tot_cons else 0.0,
        summer_t=summer_t, winter_t=winter_t, tod=tod, landed_components=comps,
        landed_cost_parts=dict(solar_cost=solar_cost, trans_chg=trans_chg, wheel_chg=wheel_chg, fixed_chg=fixed_chg,
                               css=css, add_surcharge=add_surcharge, lapse_impact=lapse_impact, total_cost=total_cost,
                               inj_stu=inj_stu, at_wheel=at_wheel, at_buyer=at_buyer, delivered_w=delivered_w),
        resid_parts=dict(F19=F19, G19=G19, F20=F20, G20=G20, H19=H19, I19=I19),
        ledger=L, mo=mo, checks=checks, rtc_mo=rtc_mo,
        # aliases so shared Mundsar/Sheo-style insight helpers can read this R
        pre_oa=cost_before/tot_cons if tot_cons else 0.0, blended=landed,
    )

def _up_tariff_waterfall_figure(R):
    """Waterfall: how Hamirpur's landed RE tariff builds up from the ex-bus solar tariff through transmission /
       wheeling / banking loss gross-up, state transmission & wheeling charges, SLDC & LTOA fees, CSS/additional
       surcharge and lapsation impact -- then compared against the pre-OA grid cost. Every bar is a real component
       of R['landed'] (they telescope to it exactly), not illustrative numbers."""
    steps = [s for s in R["landed_components"] if s[0] == "RE Tariff (ex-bus)" or abs(s[1]) > 0.005]
    grid, landed = R["grid_before"], R["landed"]
    labels = [s[0] for s in steps] + ["Landed RE Tariff"]
    values = [s[1] for s in steps] + [0]
    fig = go.Figure()
    fig.add_trace(go.Waterfall(
        x=labels, y=values, measure=["absolute"] + ["relative"]*(len(steps)-1) + ["total"],
        text=[f"\u20b9{v:.2f}" for v in values[:-1]] + [""],
        textposition="outside", textfont=dict(size=11, color="#333333"),
        connector=dict(line=dict(color="#CCCCCC", width=1, dash="dot")),
        increasing=dict(marker=dict(color="#8DA9C4", line=dict(color="white", width=0.5))),
        decreasing=dict(marker=dict(color="#8DA9C4", line=dict(color="white", width=0.5))),
        totals=dict(marker=dict(color="#0A4635", line=dict(color="white", width=0.5))),
        width=0.6, showlegend=False))
    fig.add_trace(go.Bar(x=["Grid Tariff (Pre-OA)"], y=[grid], marker=dict(color="#C1443B", line=dict(color="white", width=0.5)),
                          width=0.6, showlegend=False))
    pct = (grid-landed)/grid*100 if grid > 0 else 0
    y_max = max(values[:-1] + [grid, landed])
    fig.add_annotation(x="Landed RE Tariff", y=landed, xref="x", yref="y", yshift=20, showarrow=False,
        text=f"<b>\u20b9{landed:.2f}</b>", bordercolor="#0A4635", borderwidth=1.2, borderpad=5, bgcolor="#E8F5E9",
        font=dict(size=11.5, color="#0A4635", family="Arial"))
    fig.add_annotation(x="Grid Tariff (Pre-OA)", y=grid, xref="x", yref="y", yshift=20, showarrow=False,
        text=f"<b>\u20b9{grid:.2f}</b>", bordercolor="#C1443B", borderwidth=1.2, borderpad=5, bgcolor="#FDEDEA",
        font=dict(size=11.5, color="#C1443B", family="Arial"))
    clear_re, clear_grid = landed + y_max*0.14, grid + y_max*0.14
    bracket_y = max(clear_re, clear_grid) + y_max*0.15
    box_y = bracket_y + y_max*0.15
    bc = "#F2A93C"
    fig.add_shape(type="line", x0="Landed RE Tariff", x1="Landed RE Tariff", y0=clear_re, y1=bracket_y, xref="x", yref="y",
                  line=dict(color=bc, width=1.5, dash="dot"))
    fig.add_shape(type="line", x0="Grid Tariff (Pre-OA)", x1="Grid Tariff (Pre-OA)", y0=clear_grid, y1=bracket_y, xref="x", yref="y",
                  line=dict(color=bc, width=1.5, dash="dot"))
    fig.add_shape(type="line", x0="Landed RE Tariff", x1="Grid Tariff (Pre-OA)", y0=bracket_y, y1=bracket_y, xref="x", yref="y",
                  line=dict(color=bc, width=1.5, dash="dot"))
    lbl = f"~{pct:.0f}% reduction" if pct >= 0 else f"~{abs(pct):.0f}% increase"
    fig.add_annotation(x=len(labels)-0.5, y=box_y, xref="x", yref="y", showarrow=False, align="center",
        text=f"<b>{lbl}</b><br>in electricity<br>costs per unit", bordercolor="#DDDDDD", borderwidth=1, borderpad=7,
        bgcolor="white", font=dict(size=10.5, color="#333333", family="Arial"))
    fig.update_layout(
        title=dict(text="Breakdown of Energy Charges in Uttar Pradesh under RE Open Access",
                   font=dict(size=14, color="#1F3864", family="Arial"), x=0.5, xanchor="center"),
        font=dict(family="Arial"), height=480, yaxis_title="Energy Charges (Rs/kWh)", plot_bgcolor="white", paper_bgcolor="white",
        xaxis=dict(tickangle=-20, tickfont=dict(size=10.5), showline=True, linecolor="#DDDDDD"),
        yaxis=dict(showgrid=False, zeroline=True, zerolinecolor="#DDDDDD", zerolinewidth=1, range=[0, y_max*1.55], dtick=1,
                   tickfont=dict(size=10.5)),
        showlegend=False, margin=dict(t=55, b=70, l=15, r=15))
    return fig

def _up_sankey_figure(R):
    """Energy-flow Sankey for Hamirpur: Injected Units -> Real-Time Settlement / Banked Energy / Lapsation / T&D Loss,
       and Banked Energy -> Banking Settlement / Banking Loss. MWh; balances exactly to injection."""
    rts, banked, bc = R["tot_rtc"]/1000, R["tot_banked"]/1000, R["tot_bc"]/1000
    lapsed, td = R["lapse_total"]/1000, R["td_loss"]/1000
    node_colors = ["#1F3864", "#2E7D32", "#F2A93C", "#E65100", "#9E9E9E", "#2E7D32", "#9E9E9E"]
    src = [0, 0, 0, 0, 2, 2]
    tgt = [1, 2, 3, 4, 5, 6]
    val = [rts, banked+bc, lapsed, td, banked, bc]
    base_labels = ["Injected Units", "Real-Time Settlement", "Banked Energy", "Lapsation", "T&D Loss",
                   "Banking Settlement", "Banking Loss"]
    totals = [sum(v for s, v in zip(src, val) if s == i) or sum(v for t, v in zip(tgt, val) if t == i)
              for i in range(len(base_labels))]
    labels = [f"{l}<br>{t:,.0f} MWh" for l, t in zip(base_labels, totals)]
    def _rgba(h, a=0.35):
        h = h.lstrip("#"); return f"rgba({int(h[0:2],16)},{int(h[2:4],16)},{int(h[4:6],16)},{a})"
    fig = go.Figure(go.Sankey(
        node=dict(pad=32, thickness=18, line=dict(color="white", width=0.5), label=labels, color=node_colors),
        link=dict(source=src, target=tgt, value=val, color=[_rgba(node_colors[s]) for s in src],
                  hovertemplate="%{source.label} \u2192 %{target.label}<br>%{value:,.0f} MWh<extra></extra>")))
    fig.update_layout(height=620, font=dict(size=10), margin=dict(t=20, b=10, l=10, r=140), paper_bgcolor="white")
    return fig

def _up_utilization_insight(R):
    inj = R["tot_inj"]
    direct, banked = R["tot_rtc"]/inj*100 if inj else 0, R["tot_banked"]/inj*100 if inj else 0
    td, bl, lp = R["td_pct"]*100, R["bc_pct"]*100, R["lapse_pct"]*100
    closing = ("confirming the proposed Solar capacity is well sized to this consumption profile."
               if lp <= 5 else "with lapsation exceeding 5%, indicating the proposed capacity may be oversized "
                                "relative to this consumption profile.")
    return (f"Of every unit of solar energy injected, {direct:.0f}% is directly utilised in real time and "
            f"{banked:.0f}% is banked and later withdrawn. The remainder is lost: {td:.1f}% to transmission, "
            f"wheeling and distribution losses, {bl:.1f}% to banking charges, and {lp:.1f}% to lapsation -- {closing}")

def _up_injection_pattern_insight(R):
    gen = R["mo"]["inj"]
    avg = sum(gen)/len(gen) if gen else 0
    lo, hi = gen.index(min(gen)), gen.index(max(gen))
    return (f"Monthly injected units (pre-T&D loss) average {avg:,.0f} MWh, ranging from a low of {min(gen):,.0f} MWh "
            f"in {MABR[lo]} to a high of {max(gen):,.0f} MWh in {MABR[hi]} -- reflecting the natural seasonal "
            f"variation in solar irradiance across the year.")

def _up_tod_hours_label(slot):
    s, w = UP_TOD_HOURS_TXT[slot]
    return f"{slot} (Summer {s} | Winter {w})"

def build_up_pdf_report(capacity_rows, R, fig_cons, contract_demand_mw, voltage):
    """Customer-facing 6-page report for Hamirpur (Uttar Pradesh, Solar-only), same structure as the Mundsar report:
       cover, customer details, generator details, settlement summary (totals only -- the UP ledger settles at
       month level, not per ToD slot), financial savings (totals only), energy flow."""
    pdf = _BorderedPDF()
    pdf.set_auto_page_break(auto=True, margin=15)
    name = "Hamirpur (Solar)"
    gen_mo = R["mo"]["inj"]

    # ---- PAGE 1: Cover ----
    if UP_PLANT_SOLAR_MWP:
        cover = [("Solar Plant Capacity", f"{UP_PLANT_SOLAR_MWP:.0f} MWp / {UP_PLANT_SOLAR_MWAC:.0f} MW AC")]
    else:
        cover = [("Solar Capacity", f"{R['solar_dc']:.0f} MWp / {R['solar_ac']:.0f} MW AC")]
    _pdf_cover_page(pdf, name, "Uttar Pradesh InSTS Open Access", cover, show_footer=False)
    _pdf_letterhead_footer(pdf)

    # ---- PAGE 2: Customer Details ----
    pdf.add_page()
    _pdf_header(pdf, name, "Customer Details")
    _pdf_section_title(pdf, "Customer Profile")
    _pdf_kv_table(pdf, [("Contract Demand", f"{contract_demand_mw:.1f} MW"), ("Voltage Level", f"{voltage}"),
                        ("Annual Consumption", f"{R['tot_cons']/1e6:.2f} MU/yr")])
    _pdf_section_title(pdf, "Current Cost of Power (Pre Open Access)")
    rows, tot_mu, tot_cr = [], 0.0, 0.0
    for s in UP_SLOT_KEYS:
        d = R["tod"][s]
        tot_mu += d["cons"]/1e6; tot_cr += d["cost_cr"]
        rows.append((_up_tod_hours_label(s), f"{d['cons']/1e6:.2f}", f"Rs {d['avg_tariff']:.2f}", f"Rs {d['cost_cr']:.2f} Cr"))
    rows.append(("Total", f"{tot_mu:.2f}", f"Rs {R['grid_before']:.2f}", f"Rs {tot_cr:.2f} Cr"))
    _pdf_df_table(pdf, pd.DataFrame(rows, columns=["ToD", "Consumption (MU)", "Grid Tariff (Pre OA)", "Cost (INR Cr)"]),
                  font_size=8.5, col_widths=[85, 35, 35, 35])
    _pdf_section_title(pdf, "Monthly Consumption Trend")
    _pdf_add_chart(pdf, fig_cons, title="Month-on-Month Consumption (ToD-wise)")
    _pdf_key_insight_box(pdf, "Consumption pattern", _mundsar_consumption_pattern_insight(R))

    # ---- PAGE 3: Generator Details ----
    pdf.add_page()
    _pdf_header(pdf, name, "Generator Details")
    _pdf_section_title(pdf, "Proposed Capacity & RE Tariff")
    _pdf_kv_table(pdf, capacity_rows + [("RE Tariff - ex-bus (INR/kWh)", f"Rs {R['ex_bus']:.2f} /kWh"),
                                        ("Landed RE Tariff (INR/kWh)", f"Rs {R['landed']:.2f} /kWh")])
    _pdf_section_title(pdf, "Injected Units by ToD (Pre-T&D)")
    irows, tot_inj = [], 0.0
    for s in UP_SLOT_KEYS:
        v = R["tod"][s]["injected"]/1e6; tot_inj += v
        irows.append((_up_tod_hours_label(s), f"{v:.2f}"))
    irows.append(("Total", f"{tot_inj:.2f}"))
    _pdf_df_table(pdf, pd.DataFrame(irows, columns=["ToD", "Injected Units (MU, Pre-T&D)"]), font_size=9, col_widths=[120, 70])
    _pdf_section_title(pdf, "Monthly Injection Trend")
    _pdf_add_chart(pdf, _mundsar_monthly_injection_total_figure(gen_mo))
    _pdf_key_insight_box(pdf, "Injection pattern", _up_injection_pattern_insight(R))

    # ---- PAGE 4: Settlement Summary (totals only) ----
    pdf.add_page()
    _pdf_header(pdf, name, "Settlement Summary")
    _pdf_section_title(pdf, "Consumption & Settlement")
    disp = R["settled"]/R["tot_cons"]*100 if R["tot_cons"] > 0 else 0
    sdf = pd.DataFrame([("Total", f"{R['tot_cons']/1e6:.2f}", f"{R['tot_rtc']/1e6:.2f}", f"{R['tot_banked']/1e6:.2f}",
                         f"{R['settled']/1e6:.2f}", f"{disp:.1f}%")],
                       columns=["", "Consumption (MU)", "RTS (MU)", "Banking (MU)", "Settled Units (MU)", "Displacement %"])
    _pdf_df_table(pdf, sdf, font_size=8.5)
    _pdf_section_title(pdf, "Month-on-Month Settlement")
    _pdf_add_chart(pdf, _mundsar_settled_residual_stacked_figure(R))
    _pdf_key_insight_box(pdf, "Settlement consistency across the year", _sheo_settlement_trend_insight(R))

    # ---- PAGE 5: Financial Savings (totals only) ----
    pdf.add_page()
    _pdf_header(pdf, name, "Financial Savings")
    _pdf_section_title(pdf, "Tariff & Savings")
    fdf = pd.DataFrame([("Total", f"Rs {R['grid_before']:.2f}", f"Rs {R['post_oa_blended']:.2f}",
                         f"Rs {R['grid_before']-R['post_oa_blended']:.2f}", f"{R['tot_cons']/1e6:.2f}", f"Rs {R['sav_cr']:.2f} Cr")],
                       columns=["", "Power Cost (Pre OA INR/kWh)", "Power Cost (Post OA INR/kWh)", "Savings per Unit",
                                "Consumption (MU)", "Savings (INR Cr)"])
    _pdf_df_table(pdf, fdf, font_size=8)
    _pdf_add_chart(pdf, _up_tariff_waterfall_figure(R), height_px=400)
    pdf.ln(3)
    _pdf_add_chart(pdf, _mundsar_total_tariff_figure(R["tot_cons"]/1000, R["settled"]/1000, R["grid_before"], R["post_oa_blended"]),
                   height_px=400)
    pdf.ln(3)
    _pdf_key_insight_box(pdf, "Tariff reduction and annual savings", _mundsar_financial_insight(R))

    # ---- PAGE 6: Energy Flow ----
    pdf.add_page()
    _pdf_header(pdf, name, "Energy Flow")
    _pdf_section_title(pdf, "Energy Flow")
    _pdf_add_chart(pdf, _up_sankey_figure(R), height_px=800)
    _pdf_key_insight_box(pdf, "How the injected renewable energy is used", _up_utilization_insight(R))
    _pdf_letterhead_footer(pdf)
    return bytes(pdf.output())

