# ══════════════════════════════════════════════════════════════════════════
# MAHARASHTRA (SOLAPUR-2) — Embedded hourly Solar/Wind CUF profile (8,760 hrs),
# load profile, BESS degradation curves, and MH tariff constants.
# ══════════════════════════════════════════════════════════════════════════
# Auto-generated embedded data: Maharashtra Solapur-2 hourly Solar/Wind CUF profile,
# load profile, BESS degradation curves, and tariff constants. Source: V12_Final.

# ---- Fix: SOLAR_CUF and WIND_CUF below were previously embedded shifted by a
# whole-year cyclic offset relative to the true Jan-Dec calendar the rest of
# the MH engine uses (MH_HOURLY_MONTHS, the dispatch loop's hour24 = (i%24)+1).
# Verified against MH_OA_Capacity_Estimator_V13_Fixed.xlsx's 'Input Generation'
# sheet: that sheet derives its Month label from a real date formula
# (=TEXT(FYStartDate+day_offset,"mmm"), FYStartDate = DATE(2026,1,1)), so its
# labels are calendar-correct. The old embedded arrays' "January" block matched
# that sheet's true "October" data value-for-value (confirmed on multiple
# consecutive hours, both Solar and Wind CUF). Since ToD-slot assignment and
# EPA-cap clipping are month/hour-sensitive, this scrambled which season's
# generation met which month's consumption -- producing a real, large
# displacement/banking/lapse mismatch vs Excel that had nothing to do with
# consumption input. Re-embedded directly from that sheet's Sr 1-8760 (Solar
# CUF col F, Wind CUF col I): with this fix, a 15 MWp Solar / 10 MW Wind /
