        # ── Sidebar ───────────────────────────────────────────────────────────────────
        with st.sidebar:
            st.markdown("## ⚡ Solapur 2 — Solar+Wind+BESS")
            st.caption("Maharashtra InSTS · Hourly (8,760-hr) dispatch model · Sunsure Energy")
            st.divider()

            st.markdown("### 🔆 Generation Capacity")
            solar_mw = slider_with_input("Solar OA Capacity (MWp)", 0.0, 50.0, float(MH_CONSTS["solarMWNow"]), 0.25, "mh_solar")
            wind_mw = slider_with_input("Wind Capacity (MW)", 0.0, 50.0, float(MH_CONSTS["windMWNow"]), 0.25, "mh_wind")
            epa_cap_preview = max(solar_mw / 1.5, wind_mw)
            st.markdown(f"""<div class="info">Open Access (EPA Cap), auto-calculated:<br>
            <b>{epa_cap_preview:.2f} MW</b> = MAX(Solar/1.5, Wind)</div>""", unsafe_allow_html=True)

            contract_demand_mw = st.session_state.contract_demand
            max_allowed_oa_mw = 1.3 * contract_demand_mw
            oa_compliant = epa_cap_preview <= max_allowed_oa_mw + 1e-9
            if oa_compliant:
                st.markdown(f"""<div class="info">✓ OA within Maharashtra's limit:<br>
                <b>{epa_cap_preview:.2f} MW</b> ≤ 1.3 × CD ({contract_demand_mw:.1f} MW) =
                <b>{max_allowed_oa_mw:.2f} MW</b></div>""", unsafe_allow_html=True)
            else:
                st.markdown(f"""<div class="warn">⚠ OA capacity EXCEEDS Maharashtra's 1.3×CD limit:<br>
                <b>{epa_cap_preview:.2f} MW</b> &gt; 1.3 × CD = <b>{max_allowed_oa_mw:.2f} MW</b><br>
                Reduce Solar/Wind, or go back to Step 2 to raise Contract Demand.</div>""", unsafe_allow_html=True)

            st.markdown("### 🔋 BESS")
            bess_containers = st.number_input("BESS Containers", 0, 40, int(MH_CONSTS["containersNow"]), 1)
            bess_mwh_display = bess_containers * MH_CONSTS["nameplatePerContainer"]
            st.caption(f"= {bess_mwh_display:.2f} MWh ({MH_CONSTS['nameplatePerContainer']} MWh/container)")
            bess_rental_cost_lacs_per_mw_month = st.number_input(
                "BESS Rental Cost (INR Lacs/MW/Month)", 0.0, 100.0, 0.0, 0.5)

            st.divider()
            st.markdown("### 💰 RE PPA Tariff")
            ppa_tariff = st.number_input("RE Tariff — Solar + Wind (Rs/kWh)", 1.0, 12.0,
                                          float(MH_CONSTS["ppaTariff"]), 0.01)

            st.divider()
            st.markdown("### 🔌 Grid — Maharashtra")
            voltage_level = st.selectbox("Voltage Level", MH_VOLTAGE_OPTIONS,
                                          index=MH_VOLTAGE_OPTIONS.index(voltage_selected)
                                          if voltage_selected in MH_VOLTAGE_OPTIONS else 0, key="mh_volt")
            st.caption(f"Wheeling loss: {MH_CONSTS['wheelLossByVoltage'][voltage_level]*100:.1f}%  ·  "
                       f"Wheeling charge: {'₹0.00' if voltage_level=='EHV (66kV & above)' else '₹0.81'}/kWh")

            with st.expander("Advanced — grid tariff components"):
                ht_i_a = st.number_input("HT-I-A (Rs/kWh)", 0.0, 20.0, float(MH_CONSTS["htIA"]), 0.01)
                ed_applicable_choice = st.selectbox("Electricity Duty (Grid) Applicable?",
                                                      ["Applicable", "Not Applicable"], index=0, key="mh_ed_grid")
                ed_applicable = (ed_applicable_choice == "Applicable")
                fac = st.number_input("FAC (Rs/kWh)", 0.0, 5.0, float(MH_CONSTS["fac"]), 0.01)
                tax_on_sale = st.number_input("Tax on Sale (Rs/kWh)", 0.0, 2.0, float(MH_CONSTS["taxOnSale"]),
                                               0.001, format="%.3f")
                bulk_rebate = st.number_input("Bulk Consumption Rebate (Rs/kWh)", -2.0, 2.0,
                                               float(MH_CONSTS["bulkRebate"]), 0.01)
                trans_charge = st.number_input("Transmission Charge (Rs/kWh)", 0.0, 5.0,
                                                float(MH_CONSTS["transCharge"]), 0.01)
                sldc = st.number_input("SLDC Charge (Rs/kWh)", 0.0, 1.0, float(MH_CONSTS["sldc"]), 0.01)

            with st.expander("Advanced — RE landed tariff"):
                re_ed_applicable_choice = st.selectbox("Electricity Duty (RE Landed) Applicable?",
                                                         ["Not Applicable", "Applicable"], index=0, key="mh_ed_re")
                re_ed_applicable = (re_ed_applicable_choice == "Applicable")
                st.caption("If Applicable, the New ED value is added into the RE landed tariff build-up.")

            with st.expander("Advanced — BESS charge/discharge window"):
                charge_start = st.number_input("Charge start (hr, 1-24)", 1, 24, int(MH_CONSTS["chargeStart"]))
                charge_dur = st.number_input("Charge duration (hrs)", 1, 12, int(MH_CONSTS["chargeDur"]))
                discharge_start = st.number_input("Discharge start (hr, 1-24)", 1, 24,
                                                   int(MH_CONSTS["dischargeStart"]))
                discharge_dur = st.number_input("Discharge duration (hrs)", 1, 12, int(MH_CONSTS["dischargeDur"]))

            with st.expander("25-Year Projection"):
                run_25yr = st.checkbox("Run full 25-year hourly re-dispatch", value=False)
                st.caption("Solar -0.6%/yr, Wind -0.3%/yr degradation (compounding); BESS per SoH-by-age curve.")

        # ── Consumption (from Step 2) ────────────────────────────────────────────────
        mh_load_mode = st.session_state.get("mh_load_mode", "flat")
        mh_flat_load_mw = st.session_state.get("mh_flat_load_mw", load_mw)
        mh_custom_load = st.session_state.get("mh_custom_load", None)

        # ── Calculate ─────────────────────────────────────────────────────────────────
        R = run_solapur2(
            solar_mw=solar_mw, wind_mw=wind_mw, bess_containers=bess_containers,
            ppa_tariff=ppa_tariff, voltage_level=voltage_level,
            ht_i_a=ht_i_a, fac=fac, tax_on_sale=tax_on_sale, bulk_rebate=bulk_rebate,
            trans_charge=trans_charge, sldc=sldc,
            load_mode=mh_load_mode, flat_load_mw=mh_flat_load_mw, custom_load=mh_custom_load,
            charge_start=charge_start, charge_dur=charge_dur,
            discharge_start=discharge_start, discharge_dur=discharge_dur,
            ed_applicable=ed_applicable, re_ed_applicable=re_ed_applicable,
        )

        bess_mw_for_rental = R["bess_mwh_nameplate"] / 4
        annual_bess_rental_cr = bess_rental_cost_lacs_per_mw_month * bess_mw_for_rental * 12 / 100
        net_savings_cr = R["savings_total_cr"] - annual_bess_rental_cr
        savings_good = net_savings_cr >= 0

        # ── Regulatory Compliance ────────────────────────────────────────────────────
        if not oa_compliant:
            st.markdown(f"""<div style="background:#FDECEA;border:2px solid #C1443B;border-radius:8px;
            padding:10px 16px;margin-bottom:10px;font-size:13.5px;color:#8B0000;font-weight:600;">
            🚫 NOT PERMITTED under Maharashtra Open Access rules: OA capacity ({R['epa_cap']:.2f} MW) exceeds
            1.3 × Contract Demand ({contract_demand_mw:.1f} MW) = {max_allowed_oa_mw:.2f} MW.
            Reduce Solar/Wind capacity, or go back to Step 2 to raise Contract Demand.
            </div>""", unsafe_allow_html=True)
        else:
            st.markdown(f"""<div style="background:#E8F5E9;border:1px solid #66BB6A;border-radius:8px;
            padding:6px 16px;margin-bottom:10px;font-size:12px;color:#1B5E20;">
            ✓ OA capacity ({R['epa_cap']:.2f} MW) within Maharashtra's 1.3×CD limit ({max_allowed_oa_mw:.2f} MW)
            </div>""", unsafe_allow_html=True)

        # ── Audit Checks ──────────────────────────────────────────────────────────────
        if R["all_checks_pass"]:
            check_items = "".join(f"✓ {name}" + "&nbsp;&nbsp;&nbsp;" for name in R["audit_checks"])
            st.markdown(f"""<div style="background:#E8F5E9;border:1px solid #66BB6A;border-radius:8px;
            padding:8px 16px;margin-bottom:10px;font-size:12.5px;color:#1B5E20;">
            <b>✓ All audit checks pass</b> &nbsp;—&nbsp; {check_items}
            </div>""", unsafe_allow_html=True)
        else:
            failed = [name for name, ok in R["audit_checks"].items() if not ok]
            st.markdown(f"""<div style="background:#FDECEA;border:1px solid #E57373;border-radius:8px;
            padding:8px 16px;margin-bottom:10px;font-size:12.5px;color:#B71C1C;">
            <b>⚠ Audit check failed:</b> {", ".join(failed)}
            </div>""", unsafe_allow_html=True)

        # ── Banner ────────────────────────────────────────────────────────────────────
        bg = "linear-gradient(90deg,#0A4635,#2E7D32)" if savings_good else "linear-gradient(90deg,#8B0000,#C1443B)"
        st.markdown(f"""<div style="background:{bg};border-radius:12px;padding:16px 22px;margin-bottom:12px">
        <h2 style="color:white;margin:0">⚡ Maharashtra InSTS Open Access (Solapur-2) — Solar + Wind + BESS Capacity Estimator</h2>
        <p style="color:#DDEEE5;margin:4px 0 0">
        {solar_mw:.2f} MWp Solar &nbsp;|&nbsp; {wind_mw:.2f} MW Wind &nbsp;|&nbsp;
        OA (EPA Cap) {R['epa_cap']:.2f} MW &nbsp;|&nbsp; {R['bess_mwh_nameplate']:.2f} MWh BESS ({bess_containers} containers)
        &nbsp;|&nbsp; {voltage_level} &nbsp;|&nbsp; {R['total_consumption']:,.0f} MWh/yr load
        </p></div>""", unsafe_allow_html=True)

        if R["total_disp_tod"] > 0.95 and not savings_good:
            st.markdown(f"""<div class="warn">⚠️ Oversized case: {R['total_disp_tod']*100:.1f}% displacement but
            net savings are <b>negative (₹{abs(net_savings_cr):.2f} Cr/yr)</b>. {R['lapsed_total']:,.0f} MWh/yr
            of surplus generation is going unused (lapsed) — its cost is outweighing the grid savings from
            displacement. Try reducing Solar/Wind capacity.</div>""", unsafe_allow_html=True)
        elif savings_good:
            st.markdown(f"""<div class="info">✓ Favourable case — {R['total_disp_tod']*100:.1f}% displacement with
            net savings of <b>₹{net_savings_cr:.2f} Cr/yr</b> (after ₹{annual_bess_rental_cr:.2f} Cr/yr BESS rental).
            </div>""", unsafe_allow_html=True)
        else:
            st.markdown(f"""<div class="warn">Net savings are negative (₹{net_savings_cr:.2f} Cr/yr) at
            {R['total_disp_tod']*100:.1f}% displacement — grid alternative currently cheaper once BESS rental
            (₹{annual_bess_rental_cr:.2f} Cr/yr) is factored in.</div>""", unsafe_allow_html=True)

        # ── Tabs ──────────────────────────────────────────────────────────────────────
        t1, t2, t3, t4 = st.tabs(["📊 Summary", "⚡ Settlement", "💰 Savings & Tariff", "📈 25-Year Projection"])

        # ══════════ TAB 1: SUMMARY ═══════════════════════════════════════════════════
        with t1:
            c1, c2, c3, c4 = st.columns(4)
            kpis = [
                (c1, f"{R['total_disp_tod']*100:.1f}%", "RE Displacement",
                 f"of {R['total_consumption']:,.0f} MWh/yr", "kpi-g"),
                (c2, f"{R['bess_mwh_nameplate']:.2f} MWh", "BESS Capacity", f"{bess_containers} containers", ""),
                (c3, f"₹{R['re_landed_tariff']:.2f}", "Landed RE Tariff", "incl. banking loss + lapse", "kpi-b"),
                (c4, f"₹{R['after_oa_incl']:.2f}", "Landed Grid Tariff", "after Open Access", "kpi-a"),
            ]
            for col, val, lbl, unit, cls in kpis:
                with col:
                    st.markdown(card(val, lbl, unit, cls), unsafe_allow_html=True)

            st.markdown("")
            c1, c2, c3, c4 = st.columns(4)
            kpis2 = [
                (c1, f"₹{R['savings_total_cr']:.2f} Cr", "Gross Savings",
                 f"₹{R['savings_per_unit']:.2f}/kWh blended", ""),
                (c2, f"₹{annual_bess_rental_cr:.2f} Cr", "BESS Rental Cost",
                 f"{bess_rental_cost_lacs_per_mw_month:.2f} L/MW/mo", ""),
                (c3, f"₹{net_savings_cr:.2f} Cr", "Net Savings", "after BESS rental",
                 "kpi-g" if savings_good else "kpi-r"),
                (c4, f"{R['epa_cap']:.2f} MW", "Open Access (EPA Cap)", "MAX(Solar/1.5, Wind)", ""),
            ]
            for col, val, lbl, unit, cls in kpis2:
                with col:
                    st.markdown(card(val, lbl, unit, cls), unsafe_allow_html=True)

            st.markdown("")
            c1, c2, c3, c4 = st.columns(4)
            kpis3 = [
                (c1, f"{R['total_settled_mwh']:,.0f} MWh", "Settled Units", "of total consumption", ""),
                (c2, f"{R['total_banked_mwh']:,.0f} MWh", "Banked (Cross-ToD)", "settled via banking", ""),
                (c3, f"{R['total_billed']:,.0f} MWh", "Total Billed Energy", "EPA-cap-limited", ""),
                (c4, f"{max_allowed_oa_mw:.2f} MW", "Max Allowable OA (1.3×CD)",
                 f"CD = {contract_demand_mw:.1f} MW", "kpi-g" if oa_compliant else "kpi-r"),
            ]
            for col, val, lbl, unit, cls in kpis3:
                with col:
                    if lbl:
                        st.markdown(card(val, lbl, unit, cls), unsafe_allow_html=True)

            st.markdown("")
            c1, c2 = st.columns([1.3, 0.7])
            with c1:
                labels_pie = ["Settled via RTS", "Settled via Banking", "Settled via BESS", "Residual Grid Power"]
                values_pie = [R["settled_via_rts_mwh"], R["settled_via_banking_mwh"],
                              R["settled_via_bess_mwh"], R["total_residual"]]
                total_cons_pie = sum(values_pie)
                pcts = [v/total_cons_pie*100 if total_cons_pie > 0 else 0 for v in values_pie]
                colors_pie = ["#2E7D32", "#F2A93C", "#1565C0", "#9E9E9E"]
                pie_text = [f"{lbl}<br><b>{p:.1f}%</b>" if p >= 1.0 else "" for lbl, p in zip(labels_pie, pcts)]
                fig = go.Figure(go.Pie(
                    labels=labels_pie, values=values_pie, hole=0.55, sort=False,
                    marker=dict(colors=colors_pie, line=dict(color="white", width=2)),
                    text=pie_text, textinfo="text",
                    textposition="outside", textfont=dict(size=13),
                    hovertemplate="<b>%{label}</b><br>%{value:,.0f} MWh<br>%{customdata:.2f}%<extra></extra>",
                    customdata=pcts,
                ))
                fig.update_layout(
                    title=dict(text="Consumption Settlement Mix", font=dict(size=14, color="#0A4635"),
                               x=0.5, xanchor="center"),
                    height=430, plot_bgcolor="white", paper_bgcolor="white",
                    legend=dict(orientation="h", y=-0.15, x=0.5, xanchor="center", font=dict(size=12)),
                    margin=dict(t=45, b=10, l=40, r=40),
                    annotations=[dict(text=f"<b>{R['total_disp_tod']*100:.1f}%</b><br>RE<br>Displacement",
                                       x=0.5, y=0.5, font=dict(size=13, color="#0A4635"), showarrow=False)])
                st.plotly_chart(fig, use_container_width=True)
            with c2:
                st.markdown('<div class="sec">Settlement Mix</div>', unsafe_allow_html=True)
                mix_df = pd.DataFrame({
                    "Route": ["Settled via RTS", "Settled via BESS", "Settled via Banking"],
                    "%": [f"{R['settled_via_rts_pct']*100:.1f}%", f"{R['settled_via_bess_pct']*100:.1f}%",
                          f"{R['settled_via_banking_pct']*100:.2f}%"],
                    "MWh": [f"{R['settled_via_rts_mwh']:,.0f}", f"{R['settled_via_bess_mwh']:,.0f}",
                            f"{R['settled_via_banking_mwh']:,.0f}"],
                })
                st.dataframe(mix_df, use_container_width=True, hide_index=True)

                loss_pct_df = pd.DataFrame({
                    "Metric": ["Lapses (%)", "Banking Loss (%)",
                               "BESS Charging Utilization (%)", "BESS Discharging Utilization (%)"],
                    "Value": [f"{R['lapse_pct']*100:.1f}%", f"{R['banking_loss_pct']*100:.1f}%",
                              f"{R['bess_charging_utilization']*100:.1f}%",
                              f"{R['bess_discharging_utilization']*100:.1f}%"],
                })
                st.dataframe(loss_pct_df, use_container_width=True, hide_index=True)

                st.markdown('<div class="sec">ToD-Level Displacement</div>', unsafe_allow_html=True)
                tod_disp_df = pd.DataFrame({
                    "ToD": ["ToD 1", "ToD 2", "ToD 3", "ToD 4", "Total"],
                    "Displacement %": [f"{R['tod_results']['T1']['disp']*100:.1f}%",
                                       f"{R['tod_results']['T2']['disp']*100:.1f}%",
                                       f"{R['tod_results']['T3']['disp']*100:.1f}%",
                                       f"{R['tod_results']['T4']['disp']*100:.1f}%",
                                       f"{R['total_disp_tod']*100:.1f}%"],
                })
                st.dataframe(tod_disp_df, use_container_width=True, hide_index=True)

        # ══════════ TAB 2: TOD BREAKDOWN ═══════════════════════════════════════════
        with t2:
            st.markdown('<div class="sec">Injection Unit Breakup Summary</div>', unsafe_allow_html=True)
            # "Total Injection" = Total Billed Energy (matching Excel's convention). The breakup
            # reconciles exactly: RTS + Banked + BESS Settled + Lapsed + Banking Loss + T&D Loss
            # (T&D loss recomputed on Total Billed Energy itself, not on pre-clip gross generation).
            _total_inj = R["total_billed"]
            bdf = pd.DataFrame({
                "Parameter": ["Total Injection", "RTS", "BESS Settled", "Banked", "Lapsed", "Banking Loss",
                              "T&D Loss", "Total Settled", "Residual", "RE Displacement"],
                "MU/yr": [_total_inj/1000, R["settled_via_rts_mwh"]/1000, R["settled_via_bess_mwh"]/1000,
                          R["total_banked_mwh"]/1000, R["lapsed_total"]/1000, R["total_banking_loss"]/1000,
                          R["td_loss_on_billed"]/1000,
                          R["total_settled_mwh"]/1000, R["total_residual"]/1000, None],
                "% Share": [100, R["settled_via_rts_mwh"]/_total_inj*100 if _total_inj else 0,
                            R["settled_via_bess_mwh"]/_total_inj*100 if _total_inj else 0,
                            R["total_banked_mwh"]/_total_inj*100 if _total_inj else 0,
                            R["lapsed_total"]/_total_inj*100 if _total_inj else 0,
                            R["total_banking_loss"]/_total_inj*100 if _total_inj else 0,
                            R["td_loss_on_billed"]/_total_inj*100 if _total_inj else 0,
                            R["total_settled_mwh"]/_total_inj*100 if _total_inj else 0,
                            R["total_residual"]/R["total_consumption"]*100 if R["total_consumption"] else 0,
                            R["total_disp_tod"]*100],
            })
            bdf_disp = bdf.copy()
            bdf_disp["MU/yr"] = bdf["MU/yr"].map(lambda v: f"{v:.3f}" if pd.notna(v) else "—")
            bdf_disp["% Share"] = bdf["% Share"].map(lambda v: f"{v:.2f}" if pd.notna(v) else "—")
            st.dataframe(bdf_disp, use_container_width=True, hide_index=True)

            st.markdown('<div class="sec">ToD-wise Monthly Consumption</div>', unsafe_allow_html=True)
            fig_cons = go.Figure()
            fig_cons.add_bar(name="ToD 1 (00-06)", x=MONTH_ORDER, y=R["mo"]["cons_t1"], marker_color="#1F3864")
            fig_cons.add_bar(name="ToD 2 (06-09)", x=MONTH_ORDER, y=R["mo"]["cons_t2"], marker_color="#FFC000")
            fig_cons.add_bar(name="ToD 3 (09-17)", x=MONTH_ORDER, y=R["mo"]["cons_t3"], marker_color="#2E75B6")
            fig_cons.add_bar(name="ToD 4 (17-24)", x=MONTH_ORDER, y=R["mo"]["cons_t4"], marker_color="#FF4444")
            fig_cons.add_scatter(name="Total Consumption", x=MONTH_ORDER, y=R["mo"]["cons"],
                                  mode="lines+markers+text", line=dict(color="black", width=2, dash="dash"),
                                  text=[f"{v:,.0f}" for v in R["mo"]["cons"]],
                                  textposition="top center", textfont=dict(size=9, color="black"))
            fig_cons.update_layout(barmode="stack", height=340, title="ToD-wise Consumption by Month (MWh)",
                                    yaxis_title="MWh", plot_bgcolor="white", paper_bgcolor="white",
                                    xaxis=dict(showgrid=False), yaxis=dict(gridcolor="#F0F0F0"),
                                    legend=dict(orientation="h", y=-0.2), margin=dict(t=36, b=5, l=5, r=5))
            st.plotly_chart(fig_cons, use_container_width=True)

            tod_labels = {"T1": "ToD 1 · 00:00–06:00", "T2": "ToD 2 · 06:00–09:00",
                          "T3": "ToD 3 · 09:00–17:00", "T4": "ToD 4 · 17:00–24:00"}
            tod_chart_rows = []
            for t in MH_TOD_KEYS:
                d = R["tod_results"][t]
                tod_chart_rows.append({
                    "Slot": tod_labels[t],
                    "Gross Savings (Cr)": round(d["savings"], 3),
                    "Displacement %": round(d["disp"] * 100, 1),
                })
            tod_chart_df = pd.DataFrame(tod_chart_rows)

            st.markdown('<div class="sec">ToD-Level Displacement &amp; Gross Savings</div>', unsafe_allow_html=True)
            fig2 = make_subplots(specs=[[{"secondary_y": True}]])
            fig2.add_bar(name="Displacement %", x=tod_chart_df["Slot"], y=tod_chart_df["Displacement %"],
                         marker_color="#F2A93C", secondary_y=False,
                         text=tod_chart_df["Displacement %"], texttemplate="%{text:.1f}%",
                         textposition="outside", textfont=dict(size=9))
            fig2.add_scatter(name="Gross Savings (Cr)", x=tod_chart_df["Slot"], y=tod_chart_df["Gross Savings (Cr)"],
                              mode="lines+markers+text", line=dict(color="#0A4635", width=2.5),
                              marker=dict(size=8), secondary_y=True,
                              text=tod_chart_df["Gross Savings (Cr)"], texttemplate="%{text:.2f}",
                              textposition="top center", textfont=dict(size=9, color="#0A4635"))
            fig2.update_layout(height=360, plot_bgcolor="white", paper_bgcolor="white",
                                legend=dict(orientation="h", y=-0.2), margin=dict(t=30, b=10, l=10, r=10))
            fig2.update_yaxes(title_text="Displacement %", secondary_y=False, gridcolor="#F0F0F0")
            fig2.update_yaxes(title_text="Gross Savings (Cr)", secondary_y=True, showgrid=False)
            st.plotly_chart(fig2, use_container_width=True)

            st.markdown('<div class="sec">Month-on-Month Settlement Breakdown</div>', unsafe_allow_html=True)
            fig3 = go.Figure()
            fig3.add_bar(name="Real-Time Settlement", x=MONTH_ORDER, y=R["mo"]["rts"],
                         marker_color="#2E7D32", opacity=0.9)
            fig3.add_bar(name="BESS Settlement", x=MONTH_ORDER, y=R["mo"]["bess"],
                         marker_color="#1565C0", opacity=0.9)
            fig3.add_bar(name="Banking Settlement", x=MONTH_ORDER, y=R["mo"]["banked"],
                         marker_color="#42A5F5", opacity=0.9)
            fig3.add_scatter(name="Total Settled", x=MONTH_ORDER, y=R["mo"]["settled"],
                              mode="lines+markers+text", line=dict(color="#1F3864", width=2.5), marker=dict(size=7),
                              text=[f"{v:,.0f}" for v in R["mo"]["settled"]],
                              textposition="top center", textfont=dict(size=9, color="#1F3864"))
            fig3.update_layout(barmode="stack", height=340, title="Monthly: RTS + BESS + Banking (MWh)",
                               yaxis_title="MWh", plot_bgcolor="white", paper_bgcolor="white",
                               xaxis=dict(showgrid=False), yaxis=dict(gridcolor="#F0F0F0"),
                               legend=dict(orientation="h", y=-0.2), margin=dict(t=36, b=5, l=5, r=5))
            st.plotly_chart(fig3, use_container_width=True)

