        with t4:
            up_mdf = pd.DataFrame({
                "Month": MABR, "Days": DAYS,
                "Injected Units (MWh)": [round(v) for v in R["mo"]["inj"]],
                "Delivered Units (MWh)": [round(v) for v in R["mo"]["gen"]],
                "Consumption (MWh)": [round(v) for v in R["mo"]["cons"]],
                "RTS (MWh)": [round(v) for v in R["mo"]["rts"]],
                "Banked (MWh)": [round(v) for v in R["mo"]["banked"]],
                "Settled (MWh)": [round(v) for v in R["mo"]["settled"]],
                "Lapsed (MWh)": [round(v) for v in R["mo"]["lapsed"]],
                "Disp %": [f"{R['mo']['settled'][m]/max(R['mo']['cons'][m], 1)*100:.1f}%" for m in range(12)]})
            _fmt = {c: "{:,.0f}" for c in up_mdf.columns if c.endswith("(MWh)")}
            st.dataframe(up_mdf.style.format(_fmt), use_container_width=True, hide_index=True)
            st.download_button("📥 Download CSV", up_mdf.to_csv(index=False).encode(), "uttar_pradesh_oa.csv", "text/csv")
            st.caption("Sunsure Energy · Uttar Pradesh InSTS Open Access · Pure Python · monthly-typical hourly model")

        st.markdown("---")
        _up_capacity_rows = [("Solar Capacity (MWp DC)", f"{solar_dc:.2f}"), ("Solar Capacity (MW AC)", f"{R['solar_ac']:.2f}")]
        _up_pdf = build_up_pdf_report(_up_capacity_rows, R, fig_cons, st.session_state.contract_demand, voltage)
        st.download_button("📄 Download PDF Report", _up_pdf, "hamirpur_report.pdf", "application/pdf", key="up_pdf_dl")
